"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type Mode = "day" | "nocturne"

const WORDS = { day: "Day", nocturne: "Nocturne" }

/** One composing line. Native text reserves the longer measure even before pretext arrives. */
function TypesetMode() {
  const ref = React.useRef<HTMLSpanElement>(null)

  React.useEffect(() => {
    const root = ref.current
    if (!root) return
    let cancelled = false
    let revision = 0
    let signature = ""
    const off: (() => void)[] = []

    ;(async () => {
      let lib: typeof import("@chenglou/pretext")
      try { lib = await import("@chenglou/pretext") } catch { return }
      if (cancelled) return
      const plain = root.querySelector<HTMLElement>(".db-mode-typeset-plain")!
      const pencil = root.querySelector<HTMLElement>(".db-mode-typeset-pencil")!
      const layer = root.querySelector<HTMLElement>(".db-mode-typeset-letters")!
      async function lay() {
        const version = ++revision
        const styles = [plain, pencil].map((el) => getComputedStyle(el))
        const fonts = styles.map((s) => `${s.fontStyle} ${s.fontWeight} ${s.fontSize} ${s.fontFamily}`)
        const tracking = parseFloat(styles[0].letterSpacing) || 0
        const next = fonts.join("|") + tracking
        if (next === signature) return
        try { await Promise.all(fonts.map((font) => document.fonts.load(font, "Day Nocturne"))) } catch { return }
        if (cancelled || version !== revision) return
        const measure = (s: string) => lib.measureNaturalWidth(lib.prepareWithSegments(s, fonts[0]))
        const lines = Object.fromEntries(Object.entries(WORDS).map(([mode, word]) => {
          const width = measure(word) + (word.length - 1) * tracking
          const letters = Array.from(word, (letter, i) => {
            const w = measure(letter)
            const x = measure(word.slice(0, i + 1)) - w + i * tracking
            return { letter, x, rtl: width - x - w, i, order: word.length - i - 1 }
          })
          return [mode, letters]
        })) as Record<Mode, { letter: string; x: number; rtl: number; i: number; order: number }[]>
        const used = new Set<number>()
        const glyphs: HTMLElement[] = []
        function glyph(day: typeof lines.day[number] | undefined, night: typeof lines.nocturne[number] | undefined) {
          const el = document.createElement("span")
          el.dataset.in = day && night ? "both" : day ? "day" : "nocturne"
          const ink = document.createElement("span")
          ink.textContent = (day ?? night)!.letter
          el.append(ink)
          for (const mode of ["day", "nocturne"] as const) {
            const at = (mode === "day" ? day : night) ?? (day ?? night)!
            el.style.setProperty(`--db-mode-${mode}-x`, `${at.x}px`)
            el.style.setProperty(`--db-mode-${mode}-rtl`, `${at.rtl}px`)
            el.style.setProperty(`--db-mode-${mode}-order`, String(at.i))
            el.style.setProperty(`--db-mode-${mode}-reverse`, String(at.order))
            if (!(mode === "day" ? day : night)) continue
            const other = lines[mode === "day" ? "nocturne" : "day"]
            // Preview just two sorts from the reading edge; English spelling stays intact in RTL.
            for (const direction of ["ltr", "rtl"] as const) {
              const order = direction === "ltr" ? at.i : at.order
              if (order > 1) continue
              const to = other[direction === "ltr" ? order : other.length - order - 1]
              const preview = document.createElement("i")
              preview.dataset.mode = mode
              preview.dataset.direction = direction
              preview.textContent = to.letter
              const distance = direction === "ltr" ? to.x - at.x : at.rtl - to.rtl
              preview.style.setProperty("--db-mode-preview-x", `${distance * 0.18}px`)
              el.append(preview)
            }
          }
          glyphs.push(el)
        }
        // Keep a shared glyph in the stick and glide it between its measured places.
        // These particular names have no shared glyphs, so all of them fade in place.
        lines.day.forEach((day) => {
          const match = lines.nocturne.findIndex((night, i) => !used.has(i) && night.letter === day.letter)
          if (match >= 0) used.add(match)
          glyph(day, lines.nocturne[match])
        })
        lines.nocturne.forEach((night, i) => { if (!used.has(i)) glyph(undefined, night) })
        layer.replaceChildren(...glyphs)
        signature = next
        root!.dataset.laid = ""
      }
      await lay()
      if (cancelled) return
      const resized = new ResizeObserver(() => { void lay() })
      resized.observe(root)
      const restyled = new MutationObserver(() => { void lay() })
      restyled.observe(document.documentElement, { attributeFilter: ["data-pair", "data-scheme", "data-mode", "data-key"] })
      off.push(() => resized.disconnect(), () => restyled.disconnect())
    })()

    return () => {
      cancelled = true
      off.forEach((f) => f())
      delete root.dataset.laid
    }
  }, [])

  return (
    <span ref={ref} className="db-mode-typeset">
      <span className="db-mode-typeset-measure">Nocturne</span>
      <span className="db-mode-typeset-plain" data-word="day">Day</span>
      <span className="db-mode-typeset-plain" data-word="nocturne">Nocturne</span>
      <i className="db-mode-typeset-pencil">Nocturne</i>
      <span className="db-mode-typeset-letters" />
    </span>
  )
}

type ModeToggleProps = Omit<React.ComponentProps<"button">, "children" | "onChange"> & {
  /**
   * Eight ways to draw the same choice. eclipse: a disc slides over a ring; horizon: the dot rises or sets; words: the chosen word,
   * drawn like a select, rolls to the other; fermata: the arc is an eyelid; sentence: "Read by light." and "Read by night.";
   * knockout: "midday" and "midnight", the second half reversed out of the ink as night falls; hour: 12:00 and 00:00, the hour
   * turning forward whichever way you go; typeset: one word resets into the other, letter by measured letter.
   */
  variant?: "eclipse" | "horizon" | "words" | "fermata" | "sentence" | "knockout" | "hour" | "typeset"
  /** The mode, when you hold it (controlled). */
  mode?: Mode
  /** The mode to start in, when the toggle holds it. */
  defaultMode?: Mode
  /** Called with the mode the person chose, and the click that chose it. The toggle applies nothing to the page. */
  onModeChange?: (mode: Mode, event: React.MouseEvent<HTMLButtonElement>) => void
  /** Pins a state for documentation ("hover", "focus"); set on the root. */
  "data-force"?: string
}

/**
 * The day and night toggle. One button, pressed when it is night, drawn eight ways: a disc sliding
 * across a ring, a dot above or below a hairline, a word on a hairline that rolls to the other, the fermata
 * as an eye, a sentence whose last word rolls, midday turning to midnight in an ink block, or a clock
 * turning from noon to midnight, or one word being reset by a compositor. It only reports the choice; the page applies it,
 * for instance `document.documentElement.dataset.mode = mode`.
 */
function ModeToggle({ variant = "eclipse", mode, defaultMode = "day", onModeChange, onClick, onPointerMove, onFocus, className, "data-force": force, "aria-label": label, ...props }: ModeToggleProps) {
  const [own, setOwn] = React.useState<Mode>(defaultMode)
  const now = mode ?? own
  const [preview, setPreview] = React.useState(true)
  // The hour only turns once the mode has changed, so nothing rolls on first paint.
  const [start] = React.useState(now)
  const [turned, setTurned] = React.useState(false)
  if (!turned && now !== start) setTurned(true)
  return (
    <button
      type="button"
      data-slot="mode-toggle"
      data-variant={variant}
      data-force={force}
      data-turned={variant === "hour" && turned ? "" : undefined}
      role={variant === "typeset" ? "switch" : undefined}
      aria-checked={variant === "typeset" ? now === "nocturne" : undefined}
      aria-pressed={variant === "typeset" ? undefined : now === "nocturne"}
      aria-label={label ?? "Night mode"}
      data-preview={variant === "typeset" && preview ? "" : undefined}
      onPointerMove={(e) => { if (!preview) setPreview(true); onPointerMove?.(e) }}
      onFocus={(e) => { setPreview(true); onFocus?.(e) }}
      className={cn("db-mode", className)}
      onClick={(e) => {
        onClick?.(e)
        if (e.defaultPrevented) return
        if (variant === "typeset") setPreview(false)
        const next: Mode = now === "nocturne" ? "day" : "nocturne"
        if (mode === undefined) setOwn(next)
        onModeChange?.(next, e)
      }}
      {...props}
    >
      <span className="db-mode-art" aria-hidden="true">
        {variant === "typeset" ? <TypesetMode /> : variant === "words" ? (
          <span className="db-mode-roll">
            <span>day</span>
            <span>night</span>
          </span>
        ) : variant === "sentence" ? (
          <>
            Read by{" "}
            <span className="db-mode-state">
              <span>light</span>
              <span>night</span>
            </span>
            <span className="db-mode-stop" />
          </>
        ) : variant === "knockout" ? (
          <>
            <span className="db-mode-mid">mid</span>
            <span className="db-mode-block">
              <span>day</span>
              <span>night</span>
            </span>
          </>
        ) : variant === "hour" ? (
          <span className="db-mode-hour">
            <span className="db-mode-digit"><span>1</span><span>0</span></span>
            <span className="db-mode-digit"><span>2</span><span>0</span></span>
            <span className="db-mode-min">:00</span>
          </span>
        ) : null}
      </span>
    </button>
  )
}

export { ModeToggle, type ModeToggleProps, type Mode }

@layer components {
  @property --db-mode-x { syntax: "<length>"; inherits: false; initial-value: 0px; }
  /* ── db-mode ── the day and night toggle: one button, pressed at night, drawn eight ways.
     Drawings read aria-pressed (the typeset switch reads aria-checked), one source of truth. */
  .db-mode {
    --dir: 1;
    appearance: none; border: 0; background: none; font: inherit; color: var(--db-graphite);
    display: inline-flex; align-items: center; vertical-align: middle; cursor: pointer;
    padding: 0.4em; margin: -0.4em; /* a hit area larger than the drawing, without moving anything */
    -webkit-tap-highlight-color: transparent;
    transition: color var(--db-allegro) var(--db-breath);
  }
  .db-mode:is([dir="rtl"], [dir="rtl"] *) { --dir: -1; }
  .db-mode:is(:hover, [data-force~="hover"]) { color: var(--db-ink); }
  .db-mode:focus-visible, .db-mode[data-force~="focus"] { outline: var(--db-stroke) solid var(--db-accent); outline-offset: 0; }
  .db-mode[data-force~="focus"] { outline-offset: 0; }
  .db-mode:disabled { opacity: 0.55; cursor: not-allowed; }
  .db-mode-art { position: relative; display: block; flex: none; }
  .db-mode-art::before, .db-mode-art::after { content: ""; position: absolute; }

  /* eclipse: a ring, and a disc filling it that a mask bites into. Day is the whole sun; night is a crescent on the moon's rim.
     The disc meets the ring: with a gap between them, day read as a checked radio. */
  .db-mode[data-variant="eclipse"] .db-mode-art { width: 1.5em; height: 1.5em; border-radius: 50%; border: var(--db-stroke) solid currentColor; box-sizing: border-box; }
  .db-mode[data-variant="eclipse"] .db-mode-art::before {
    inset: 0; border-radius: 50%; background: currentColor;
    --db-mode-x: 1.9em;
    -webkit-mask: radial-gradient(circle at calc(50% + var(--dir) * var(--db-mode-x)) calc(50% - var(--db-mode-x)), transparent 0.56em, #000 calc(0.56em + 0.6px));
    mask: radial-gradient(circle at calc(50% + var(--dir) * var(--db-mode-x)) calc(50% - var(--db-mode-x)), transparent 0.56em, #000 calc(0.56em + 0.6px));
    transition: --db-mode-x var(--db-andante) var(--db-breath);
  }
  .db-mode[data-variant="eclipse"][aria-pressed="true"] .db-mode-art::before { --db-mode-x: 0.34em; }

  /* horizon: a hairline, and a dot that stands above it by day, sets below it at night, and empties as it goes. */
  .db-mode[data-variant="horizon"] .db-mode-art { width: 2.2em; height: 1.8em; }
  .db-mode[data-variant="horizon"] .db-mode-art::before { inset: 50% 0 auto; border-top: var(--db-hairline) solid currentColor; }
  .db-mode[data-variant="horizon"] .db-mode-art::after {
    left: calc(50% - 0.25em); top: 0.05em; width: 0.5em; height: 0.5em; border-radius: 50%;
    box-shadow: inset 0 0 0 0.25em currentColor;
    transition: top var(--db-andante) var(--db-spiccato), box-shadow var(--db-andante) var(--db-exhale);
  }
  .db-mode[data-variant="horizon"][aria-pressed="true"] .db-mode-art::after { top: 1.25em; box-shadow: inset 0 0 0 var(--db-stroke) currentColor; }

  /* fermata: the sign as an eye. The arc is the lid over the dot; at night it comes down and closes over it. */
  .db-mode[data-variant="fermata"] .db-mode-art { width: 1.9em; height: 1.3em; }
  .db-mode[data-variant="fermata"] .db-mode-art::before {
    inset: 0 0 auto; height: 0.8em; border-top: var(--db-stroke) solid currentColor; border-radius: 50% 50% 0 0 / 100% 100% 0 0;
    transition: height var(--db-moderato) var(--db-exhale), top var(--db-moderato) var(--db-exhale);
  }
  .db-mode[data-variant="fermata"] .db-mode-art::after {
    left: calc(50% - 0.21em); top: 0.72em; width: 0.42em; height: 0.42em; border-radius: 50%; background: currentColor;
    transition: scale var(--db-moderato) var(--db-exhale);
  }
  .db-mode[data-variant="fermata"][aria-pressed="true"] .db-mode-art::before { height: 0; top: 0.93em; }
  .db-mode[data-variant="fermata"][aria-pressed="true"] .db-mode-art::after { scale: 1 0.14; }

  /* words: the choice as a word in a sentence, drawn like a select's. The word you're reading by stands in the italic on a hairline,
     with ↕ where a select has ↓: the other word is above or below it, not in a list. Choosing rolls it the way the sun goes,
     everything down into night and up into day, and the line narrows or widens to the new word. */
  .db-mode[data-variant="words"] { align-items: baseline; vertical-align: baseline; }
  .db-mode[data-variant="words"] .db-mode-art { display: inline-flex; align-items: baseline; }
  .db-mode-roll {
    display: inline-grid; align-items: baseline; overflow: clip; interpolate-size: allow-keywords;
    padding: 0 0.6em 0.1em 0; /* a select's: the arrow sits in the end padding, the hairline under the descenders */
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1.2; color: var(--db-ink);
    background: linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 100% / calc(100% - 0.6em) var(--db-hairline);
  }
  .db-mode-roll:is([dir="rtl"], [dir="rtl"] *) { padding-inline: 0.6em 0; background-position: 100% 100%; }
  .db-mode-roll > * {
    grid-area: 1 / 1; justify-self: start; white-space: nowrap;
    transition: translate var(--db-moderato) var(--db-breath), opacity var(--db-moderato) var(--db-breath), inline-size var(--db-moderato) var(--db-breath);
  }
  /* The word that isn't chosen takes no width and waits out of the clip: day below the line, night above it. */
  .db-mode[aria-pressed="true"] .db-mode-roll > :first-child { translate: 0 130%; opacity: 0; inline-size: 0; }
  .db-mode[aria-pressed="false"] .db-mode-roll > :last-child { translate: 0 -130%; opacity: 0; inline-size: 0; }
  .db-mode[data-variant="words"] .db-mode-art::after {
    content: "↕" / ""; inset-inline-end: 0; bottom: 0.3em; /* in the roll's end padding, where a select's arrow sits in its own */
    font-family: var(--db-voice); font-size: 0.72em; line-height: 1; color: var(--db-pencil); pointer-events: none;
    transition: translate var(--db-moderato) var(--db-exhale), color var(--db-allegro);
  }
  .db-mode[data-variant="words"]:is(:hover, [data-force~="hover"]) .db-mode-roll { background-image: linear-gradient(var(--db-ink), var(--db-ink)); }
  .db-mode[data-variant="words"]:is(:hover, [data-force~="hover"]) .db-mode-art::after { color: var(--db-ink); translate: 0 var(--nudge, -2px); }
  .db-mode[data-variant="words"][aria-pressed="true"]:is(:hover, [data-force~="hover"]) { --nudge: 2px; } /* toward the word you would get: night waits above, day below */

  /* sentence: "Read by light." and "Read by night." The last word rolls the way the sun goes: light rises in from below, night sets in from above. The full stop is a dot by day and a ring by night. */
  .db-mode[data-variant="sentence"] .db-mode-art { white-space: nowrap; }
  .db-mode-state {
    display: inline-grid; vertical-align: baseline; overflow: clip;
    padding: 0.12em 0.14em 0.24em; margin-block: -0.12em -0.24em; margin-inline: -0.08em -0.14em;
    font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1; color: var(--db-ink);
    background: linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0.14em calc(100% - 0.1em) / calc(100% - 0.28em) var(--db-hairline);
    transition: background-color var(--db-moderato);
  }
  .db-mode-state > span { grid-area: 1 / 1; transition: translate var(--db-moderato) var(--db-breath), opacity var(--db-moderato) var(--db-breath); }
  .db-mode[aria-pressed="true"] .db-mode-state > :first-child { translate: 0 110%; opacity: 0; }
  .db-mode[aria-pressed="false"] .db-mode-state > :last-child { translate: 0 -110%; opacity: 0; }
  .db-mode:is(:hover, [data-force~="hover"]) .db-mode-state { background-image: linear-gradient(var(--db-ink), var(--db-ink)); }
  .db-mode-stop {
    display: inline-block; width: max(0.22em, 5px); height: max(0.22em, 5px); margin-inline-start: 0.24em; border-radius: 50%;
    box-shadow: inset 0 0 0 0.5em currentColor; transition: box-shadow var(--db-andante) var(--db-exhale);
  }
  .db-mode[aria-pressed="true"] .db-mode-stop { box-shadow: inset 0 0 0 var(--db-hairline) currentColor; }

  /* knockout: after "the uncreative", where part of a word is reversed out of an ink block. "mid" stays heavy roman on the paper;
     the half you chose is the italic. By day it reads midday. At night the ink falls over the second half from above, the way
     nocturne falls over the page, and night reverses out of it; at dawn the ink lifts. Pointing lets a sliver fall, or lifts it a little. */
  .db-mode[data-variant="knockout"] { align-items: baseline; vertical-align: baseline; color: var(--db-ink); }
  .db-mode[data-variant="knockout"] .db-mode-art { display: inline-flex; align-items: baseline; white-space: nowrap; }
  .db-mode-mid { font-weight: 760; letter-spacing: -0.03em; }
  .db-mode-block {
    --fall: 0; position: relative; isolation: isolate; display: inline-grid; align-items: baseline; overflow: clip; interpolate-size: allow-keywords;
    padding: 0.04em 0.16em 0.1em 0.06em; margin-block: -0.04em -0.1em;
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1.05;
    color: var(--db-ink); transition: color var(--db-moderato) var(--db-breath);
  }
  .db-mode-block::before {
    content: ""; position: absolute; inset: 0; z-index: -1; background: var(--db-ink);
    scale: 1 var(--fall); transform-origin: 50% 0; transition: scale var(--db-moderato) var(--db-breath);
  }
  .db-mode-block > * { grid-area: 1 / 1; justify-self: start; transition: opacity var(--db-moderato) var(--db-breath), inline-size var(--db-moderato) var(--db-breath); }
  .db-mode[data-variant="knockout"][aria-pressed="true"] .db-mode-block { --fall: 1; color: var(--db-paper); }
  .db-mode[data-variant="knockout"][aria-pressed="true"] .db-mode-block > :first-child,
  .db-mode[data-variant="knockout"][aria-pressed="false"] .db-mode-block > :last-child { opacity: 0; inline-size: 0; }
  .db-mode[data-variant="knockout"][aria-pressed="false"]:is(:hover, [data-force~="hover"]) .db-mode-block { --fall: 0.14; }
  .db-mode[data-variant="knockout"][aria-pressed="true"]:is(:hover, [data-force~="hover"]) .db-mode-block { --fall: 0.86; }
  .db-mode[data-variant="knockout"]:disabled .db-mode-block::before { background: var(--db-pencil); }

  /* hour: after the numbers used as data in "the silence that heals". Noon by day, midnight at night: 12:00 and 00:00, the hour
     yours in the italic and the minutes ours in pencil. A clock only goes forward, so whichever way you choose the hour turns
     forward: out at the top, in from below, the units first and the tens one step behind, like a carry. */
  .db-mode[data-variant="hour"] { align-items: baseline; vertical-align: baseline; }
  .db-mode-hour { display: inline-flex; align-items: baseline; direction: ltr; unicode-bidi: isolate; font-variant-numeric: tabular-nums lining-nums; line-height: 1; }
  .db-mode-digit {
    display: inline-grid; overflow: clip; padding-block: 0.1em; margin-block: -0.1em;
    font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * 1em); color: var(--db-ink);
  }
  .db-mode-digit > * { grid-area: 1 / 1; text-align: center; }
  .db-mode-min { margin-inline-start: 0.04em; color: var(--db-pencil); transition: color var(--db-allegro); }
  .db-mode[data-variant="hour"]:is(:hover, [data-force~="hover"]) .db-mode-min { color: var(--db-ink); }
  .db-mode[aria-pressed="false"] .db-mode-digit > :last-child, .db-mode[aria-pressed="true"] .db-mode-digit > :first-child { opacity: 0; translate: 0 -110%; }
  .db-mode[data-turned][aria-pressed="true"] .db-mode-digit > :last-child { animation: db-hour-in var(--db-moderato) var(--db-exhale) backwards; }
  .db-mode[data-turned][aria-pressed="true"] .db-mode-digit > :first-child { animation: db-hour-out var(--db-allegro) var(--db-breath) backwards; }
  .db-mode[data-turned][aria-pressed="false"] .db-mode-digit > :first-child { animation: db-hour-in-again var(--db-moderato) var(--db-exhale) backwards; }
  .db-mode[data-turned][aria-pressed="false"] .db-mode-digit > :last-child { animation: db-hour-out-again var(--db-allegro) var(--db-breath) backwards; }
  .db-mode[data-turned] .db-mode-digit:first-child > * { animation-delay: calc(var(--db-arpeggio) * 3); }
  @keyframes db-hour-in { from { opacity: 0; translate: 0 110%; } to { opacity: 1; translate: 0 0; } }
  @keyframes db-hour-in-again { from { opacity: 0; translate: 0 110%; } to { opacity: 1; translate: 0 0; } }
  @keyframes db-hour-out { from { opacity: 1; translate: 0 0; } to { opacity: 0; translate: 0 -110%; } }
  @keyframes db-hour-out-again { from { opacity: 1; translate: 0 0; } to { opacity: 0; translate: 0 -110%; } }

  /* typeset: one line in the composing stick. The hidden longer word reserves its measure;
     only the current word prints. Pointing pencils in two sorts from the other word. */
  .db-mode[data-variant="typeset"] { min-block-size: 44px; flex: none; font-size: inherit; transition: none; }
  .db-mode-typeset {
    position: relative; display: block; white-space: nowrap; text-align: start;
    font-family: var(--db-voice); font-style: normal; font-weight: 400; font-size: 1em;
    line-height: 1.45; letter-spacing: 0; font-stretch: normal; font-kerning: normal; font-optical-sizing: auto;
  }
  .db-mode-typeset-measure { visibility: hidden; }
  .db-mode-typeset-plain, .db-mode-typeset-pencil { position: absolute; inset-block-start: 0; inset-inline-start: 0; }
  .db-mode-typeset-pencil { visibility: hidden; font-family: var(--db-expression); font-style: italic; font-size: calc(1em * var(--db-expression-scale)); }
  .db-mode[aria-checked="true"] .db-mode-typeset-plain[data-word="day"],
  .db-mode[aria-checked="false"] .db-mode-typeset-plain[data-word="nocturne"] { visibility: hidden; }
  .db-mode-typeset-letters { display: none; }
  .db-mode-typeset[data-laid] .db-mode-typeset-plain { visibility: hidden; }
  .db-mode-typeset[data-laid] .db-mode-typeset-letters { display: contents; }
  .db-mode-typeset-letters > span {
    --db-mode-day-x: 0px; --db-mode-nocturne-x: 0px; --db-mode-day-rtl: 0px; --db-mode-nocturne-rtl: 0px;
    --db-mode-day-order: 0; --db-mode-nocturne-order: 0; --db-mode-day-reverse: 0; --db-mode-nocturne-reverse: 0;
    --db-mode-x: var(--db-mode-day-x); --db-mode-order: var(--db-mode-day-order);
    --db-mode-show: 1; --db-mode-wait: calc(var(--db-allegro) / 2);
    position: absolute; inset-inline-start: 0; inset-block-start: 0;
    translate: calc(var(--dir) * var(--db-mode-x)) 0; opacity: var(--db-mode-show);
    transition: translate var(--db-moderato) var(--db-exhale), opacity var(--db-allegro) var(--db-breath);
    transition-delay: calc(var(--db-mode-wait) + var(--db-mode-order) * var(--db-arpeggio) / 3);
  }
  .db-mode[aria-checked="true"] .db-mode-typeset-letters > span { --db-mode-x: var(--db-mode-nocturne-x); --db-mode-order: var(--db-mode-nocturne-order); }
  .db-mode:is([dir="rtl"], [dir="rtl"] *) .db-mode-typeset-letters > span { --db-mode-x: var(--db-mode-day-rtl); --db-mode-order: var(--db-mode-day-reverse); }
  .db-mode[aria-checked="true"]:is([dir="rtl"], [dir="rtl"] *) .db-mode-typeset-letters > span { --db-mode-x: var(--db-mode-nocturne-rtl); --db-mode-order: var(--db-mode-nocturne-reverse); }
  .db-mode[aria-checked="false"] .db-mode-typeset-letters > [data-in="nocturne"],
  .db-mode[aria-checked="true"] .db-mode-typeset-letters > [data-in="day"] { --db-mode-show: 0; --db-mode-wait: 0ms; }
  .db-mode-typeset-letters > span > span { transition: opacity var(--db-allegro) var(--db-breath); }
  .db-mode-typeset-letters i {
    --db-mode-preview-x: 0px;
    display: none; position: absolute; inset-inline-start: 0; inset-block-start: 0;
    font-family: var(--db-expression); font-size: calc(1em * var(--db-expression-scale)); font-style: italic;
    line-height: calc(1.45 / var(--db-expression-scale)); color: var(--db-pencil);
    opacity: var(--db-mode-preview, 0); translate: calc(var(--db-mode-preview, 0) * var(--db-mode-preview-x)) 0;
