  .db-mode[aria-checked="true"] .db-mode-typeset-letters i[data-mode="nocturne"][data-direction="ltr"] { display: block; }
  .db-mode:is([dir="rtl"], [dir="rtl"] *) .db-mode-typeset-letters i[data-direction="ltr"] { display: none; }
  .db-mode[aria-checked="false"]:is([dir="rtl"], [dir="rtl"] *) .db-mode-typeset-letters i[data-mode="day"][data-direction="rtl"],
  .db-mode[aria-checked="true"]:is([dir="rtl"], [dir="rtl"] *) .db-mode-typeset-letters i[data-mode="nocturne"][data-direction="rtl"] { display: block; }
  @media (prefers-reduced-motion: no-preference) {
    .db-mode[data-variant="typeset"][data-preview]:not(:disabled):not([data-force~="reduced"]):is(:hover, :focus-visible, [data-force~="hover"], [data-force~="focus"]) { --db-mode-preview: 0.75; }
  }
  .db-mode:not([data-preview]) .db-mode-typeset-letters > span > * { transition: none; }
  .db-mode-typeset-letters > span:has(i[data-direction="ltr"]) > span { opacity: calc(1 - var(--db-mode-preview, 0)); }
  .db-mode:is([dir="rtl"], [dir="rtl"] *) .db-mode-typeset-letters > span > span { opacity: 1; }
  .db-mode:is([dir="rtl"], [dir="rtl"] *) .db-mode-typeset-letters > span:has(i[data-direction="rtl"]) > span { opacity: calc(1 - var(--db-mode-preview, 0)); }

  /* The appearance hook supplies the origin and guards support/reduced motion. Its new root
     opens from the toggle; the old sheet stays still, with no cross-fade. Both finish moderato. */
  :root:has(.bar-mode[data-variant="typeset"]) body { transition: none; }
  :root:has(.bar-mode[data-variant="typeset"])::view-transition-old(root) { animation: none; mix-blend-mode: normal; }
  :root:has(.bar-mode[data-variant="typeset"])::view-transition-new(root) { animation: db-mode-paper-in var(--db-moderato) var(--db-breath) both; mix-blend-mode: normal; }
  :root:has(.bar-mode[data-variant="typeset"])::view-transition { pointer-events: none; }
  @keyframes db-mode-paper-in {
    from { clip-path: circle(0 at var(--db-appearance-x, 50%) var(--db-appearance-y, 0)); }
    to { clip-path: circle(150vmax at var(--db-appearance-x, 50%) var(--db-appearance-y, 0)); }
  }
  .db-mode[data-force~="reduced"] { --db-mode-preview: 0; }
  .db-mode[data-force~="reduced"] .db-mode-typeset-letters > span,
  .db-mode[data-force~="reduced"] .db-mode-typeset-letters > span > * { transition: none; }
  @media (prefers-reduced-motion: reduce) {
    .db-mode[data-variant="typeset"] { --db-mode-preview: 0; transition: none; }
    .db-mode-typeset-letters > span, .db-mode-typeset-letters > span > * { transition: none; }
    :root:has(.bar-mode[data-variant="typeset"])::view-transition-old(root),
    :root:has(.bar-mode[data-variant="typeset"])::view-transition-new(root) { animation: none; }
  }

  /* Forced colours drop backgrounds and masks' colours: say what each part is. */
  @media (forced-colors: active) {
    .db-mode { color: ButtonText; }
    .db-mode:focus-visible, .db-mode[data-force~="focus"] { outline-color: Highlight; }
    .db-mode-art::before, .db-mode-art::after, .db-mode-roll, .db-mode-state { forced-color-adjust: none; }
    .db-mode[data-variant="eclipse"] .db-mode-art::before, .db-mode[data-variant="fermata"] .db-mode-art::after { background: ButtonText; }
    .db-mode-roll, .db-mode-state { color: ButtonText; background-image: linear-gradient(ButtonText, ButtonText); }
    .db-mode-block, .db-mode-block::before, .db-mode-digit, .db-mode-min { forced-color-adjust: none; color: ButtonText; }
    .db-mode-block::before { background: ButtonText; }
    .db-mode[aria-pressed="true"] .db-mode-block { color: ButtonFace; }
    .db-mode-typeset, .db-mode-typeset-letters i { color: ButtonText; }
  }
}
